def reference_fault(text, name):
    if name=='v59_old_length':
        lines=text.splitlines(keepends=True);hits=[]
        for i,line in enumerate(lines):
            fields=line.split()
            if fields and fields[0] in ['Rsc_DN', 'Rsc_DP', 'Rsd_DN', 'Rsd_DP']:
                assert line.count(' l=5u ')==1
                lines[i]=line.replace(' l=5u ',' l=7.4u ');hits.append(fields[0])
        assert sorted(hits)==['Rsc_DN', 'Rsc_DP', 'Rsd_DN', 'Rsd_DP']
        return ''.join(lines)
